from functools import lru_cache

def transform(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    # L trimino orientation colors determined by examples; square color 1.
    shapes={1:((0,0),(0,1),(1,0),(1,1)),
            2:((0,1),(1,0),(1,1)),
            3:((0,0),(0,1),(1,1)),
            4:((0,0),(1,0),(1,1)),
            5:((0,0),(0,1),(1,0)),}
    candidates=[]
    for color,shape in shapes.items():
      for r in range(len(grid)):
       for c in range(len(grid[0])):
        tile={(r+dr,c+dc) for dr,dc in shape}
        if tile<=cells: candidates.append((tile,color))
    bycell={p:[] for p in cells}
    for i,(tile,col) in enumerate(candidates):
      for p in tile: bycell[p].append(i)
    @lru_cache(None)
    def solve(rem):
      rem=set(rem)
      if not rem:return ()
      p=min(rem,key=lambda q:sum(candidates[i][0]<=rem for i in bycell[q]))
      for i in bycell[p]:
        tile,col=candidates[i]
        if tile<=rem:
          rest=solve(tuple(sorted(rem-tile)))
          if rest is not None:return (i,)+rest
      return None
    chosen=solve(tuple(sorted(cells)))
    out=[[0 for _ in row] for row in grid]
    if chosen is not None:
      for i in chosen:
        tile,col=candidates[i]
        for r,c in tile:out[r][c]=col
    return out
